/**
 * STATIC MODULE REGISTRY - single source of truth for progress denominators.
 *
 * Every implementation checklist item in the application is listed here at build
 * time. Nothing is ever "discovered" by navigating to a page, so counts can never
 * change as the user moves around the app.
 *
 * Item key format: "<page storage id>::step<n>::<item id>"
 * Generated from the module pages; keep in sync when checklist items change.
 */

export type CategoryKey =
  | 'foundation'
  | 'governance'
  | 'outcomes'
  | 'crossCutting'
  | 'enablement'
  | 'monitoring';

export interface ModuleDefinition {
  /** Canonical module id, e.g. "CD-F1" */
  id: string;
  /** Display name used in activity logs and badges */
  name: string;
  /** Category (phase) this module belongs to */
  category: CategoryKey;
  /** Page-level storage ids that contribute checklist items to this module */
  storageIds: string[];
  /** Fixed, complete list of checklist item keys for this module */
  items: string[];
}

export const CATEGORY_NAMES: Record<CategoryKey, string> = {
  foundation: 'Foundation',
  governance: 'Governance & Planning',
  outcomes: 'Four Outcomes',
  crossCutting: 'Cross-Cutting',
  enablement: 'Enablement',
  monitoring: 'Monitoring & Assurance',
};

